import type { Region, Severity } from '@/ml/types';
import { assetUrl } from '@/utils/assetUrl';

/**
 * Bundled demo sample sets (public/demo/). The images are SYNTHETIC
 * illustrations generated by `scripts/generate_demo_samples.py` — not real
 * patient photos — tinted to represent different hemoglobin levels, so
 * reviewers can run the whole pipeline on a laptop without a camera.
 */
export interface DemoSet {
  id: string;
  /** Intended level the images were generated for (adult woman reference). */
  level: Severity;
  approxHb: number;
  images: Record<Region, string>;
}

const set = (id: string, level: Severity, approxHb: number): DemoSet => ({
  id,
  level,
  approxHb,
  images: { eye: `demo/${id}_eye.jpg`, nails: `demo/${id}_nails.jpg`, palm: `demo/${id}_palm.jpg` },
});

export const DEMO_SETS: DemoSet[] = [
  set('healthy', 'normal', 13.4),
  set('mild', 'mild', 11.5),
  set('moderate', 'moderate', 9.2),
  set('severe', 'severe', 6.6),
];

export async function loadDemoImage(path: string): Promise<Blob> {
  const res = await fetch(assetUrl(path));
  if (!res.ok) throw new Error(`Demo image missing: ${path}`);
  return res.blob();
}
